/** Generated by scaffold-crud-pages. Query hooks for NotificationTemplates.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchNotificationTemplatesList,
  fetchNotificationTemplatesById,
  createNotificationTemplates,
  updateNotificationTemplates,
  deleteNotificationTemplates,
  type FetchNotificationTemplatesListParams,
} from '~/services/httpServices/notificationTemplatesService';
import type { CreateNotificationTemplatesRequest, UpdateNotificationTemplatesRequest } from '~/types/notification-templates';

const DOMAIN = 'notificationTemplates';

export function useNotificationTemplatesList(params?: FetchNotificationTemplatesListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchNotificationTemplatesList(params),
  });
}

export function useNotificationTemplates(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchNotificationTemplatesById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateNotificationTemplates() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateNotificationTemplatesRequest) => createNotificationTemplates(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateNotificationTemplates() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateNotificationTemplatesRequest }) =>
      updateNotificationTemplates(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteNotificationTemplates() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteNotificationTemplates(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
